   GOLDEN ARROW — Level 1: Balloon Meadow
   Single-file canvas game. Art: golden-hour silhouette style.
   Audio: WebAudio synth only (no files).
   Aim with the pointer, hold to draw the bow, release to loose.
   Pop 15 balloons in 60s. Out of time or arrows = defeat.
   ============================================================ */

const cv = document.getElementById('c');
const ctx = cv.getContext('2d');
let W=0,H=0,DPR=1;
function resize(){
  DPR = Math.min(window.devicePixelRatio||1, 2);
  W = window.innerWidth; H = window.innerHeight;
  cv.width = W*DPR; cv.height = H*DPR;
  ctx.setTransform(DPR,0,0,DPR,0,0);
}
addEventListener('resize', resize); resize();

/* ---------------- palette (roles) ---------------- */
