  skyTop:'#232c52', skyMid:'#5b4a7a', skyHot:'#e8894f', skyLow:'#f6c06a',
  hillFar:'#3b3f68', hillMid:'#2a2f52', hillNear:'#1a2040',
  ground:'#161b34', grass:'#0e1228',
  ink:'#f6efe3', accent:'#f5b942', danger:'#e7574c',
  good:'#7bd36b',
};
